const e=JSON.parse('{"key":"v-a76073fc","path":"/lc2944.html","title":"2944. 购买水果需要的最少金币数","lang":"en-US","frontmatter":{"tag":"dp"},"headers":[{"level":2,"title":"解析","slug":"解析","link":"#解析","children":[]},{"level":2,"title":"代码","slug":"代码","link":"#代码","children":[]}],"git":{"createdTime":1737726404000,"updatedTime":1737726404000,"contributors":[{"name":"HouShengming","email":"18865290907@163.com","commits":1}]},"readingTime":{"minutes":2.47,"words":740},"filePathRelative":"lc2944.md","localizedDate":"January 24, 2025","excerpt":"<h1> 2944. 购买水果需要的最少金币数</h1>\\n<p>给你一个 <strong>下标从 <code>1</code> 开始的</strong> 整数数组 <code>prices</code> ，其中 <code>prices[i]</code> 表示你购买第 <code>i</code> 个水果需要花费的金币数目。</p>\\n<p>水果超市有如下促销活动：</p>\\n<p>如果你花费 <code>prices[i]</code> 购买了下标为 <code>i</code> 的水果，那么你可以免费获得下标范围在 <code>[i + 1, i + i]</code> 的水果。\\n注意 ，即使你 <strong>可以</strong> 免费获得水果 <code>j</code> ，你仍然可以花费 <code>prices[j]</code> 个金币去购买它以获得它的奖励。</p>"}');export{e as data};
